-- no STANDBY:
SELECT process, pid, status, client_process, thread#, sequence#, block#
FROM v$managed_standby
WHERE process IN ('MRP0','RFS','ARCH') ORDER BY process;

SELECT name, role, action, sequence#, block#
FROM v$dataguard_process WHERE role LIKE '%apply%' OR name LIKE '%MRP%';

-- no STANDBY:
SELECT thread#, low_sequence#, high_sequence# FROM v$archive_gap;

-- ultima sequencia recebida x aplicada:
SELECT thread#,
       MAX(CASE WHEN applied = 'YES' THEN sequence# END) AS aplicada,
       MAX(sequence#) AS recebida
FROM v$archived_log GROUP BY thread#;

-- no PRIMARIO, a sequencia atual:
SELECT thread#, MAX(sequence#) AS atual FROM v$archived_log
WHERE dest_id = 1 GROUP BY thread#;

-- parar (se estiver em estado inconsistente):
ALTER DATABASE RECOVER MANAGED STANDBY DATABASE CANCEL;

-- religar em background, sem travar a sessao:
ALTER DATABASE RECOVER MANAGED STANDBY DATABASE
  USING CURRENT LOGFILE DISCONNECT FROM SESSION;

-- no PRIMARIO, gerar os archives que faltam:
RMAN> BACKUP ARCHIVELOG FROM SEQUENCE <low> UNTIL SEQUENCE <high>
      THREAD <n> FORMAT '/tmp/gap_%s.bkp';

-- copiar para o standby e catalogar/restaurar la:
RMAN> CATALOG START WITH '/tmp/';
RMAN> RESTORE ARCHIVELOG FROM SEQUENCE <low> UNTIL SEQUENCE <high>;
